Translate("deDE", "razorfen-downs", {
	title = "Die Hügel von Razorfen",
	aliases = { "die Hügel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Hügel von Razorfen sind ein gewaltiges Labyrinth aus riesigen Dornen am Südrand des {link:the-barrens}Brachlands{/link}, wo die Ebenen nach {link:thousand-needles}Tausend Nadeln{/link} hin abfallen. Die {link:quilboar}Stacheleber{/link} halten sie für den heiligsten all ihrer Orte. Ihr Tor ist eine Höhle in den Dornen, geformt wie der offene Rachen eines großen Ebers. Unter der Dornenkuppel liegen die Begräbnisstätten ihres Volkes und der Sitz ihrer Hohepriester. Nun ruhen die Toten der Hügel nicht mehr. Die {link:scourge}Geißel{/link} ist nach {link:kalimdor}Kalimdor{/link} gekommen und hat das heilige Labyrinth zu einer Festung der Toten gemacht.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die {link:quilboar}Stacheleber{/link} sagen, dass der Halbgott Agamaggan vor langer Zeit im {link:the-barrens}Brachland{/link} fiel und dass überall dort Dornen wuchsen, wo sein Blut die Erde berührte. Das größte dieser Dickichte ist das Razorfen, das sie für seinen Leib selbst halten. Die Hügel und {link:razorfen-kraul}der Kral von Razorfen{/link} erhoben sich aus denselben mächtigen Ranken. Der eingesperrte Mystiker {link:mangletooth}Mangletooth{/link} sagt, die Hügel seien der heiligste Ort von allen, denn ihr Eingang sei Agamaggans eigener Schlund, der jene verschlingt, die ihm nicht treu sind. Keine Chronik verzeichnet, wann die Stacheleber sich hier zuerst niederließen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Ein Lich namens {link:amnennar-the-coldbringer}Amnennar der Kältebringer{/link} herrscht über die Hügel. Die Hohepriester der {link:quilboar}Stacheleber{/link}, die {link:death-s-head}Totenkopf{/link}, haben sich an ihn gebunden, und viele aus ihrem Stamm wandeln nun als verdorrte Untote. Skelette marschieren durch die Tunnel, und eine große Monstrosität mästet sich an den Toten. Die Stacheleber schleppen Gefangene aus dem ganzen {link:the-barrens}Brachland{/link} hierher. Nahe dem Eingang steht ein Götzenbild, an dem diese Gefangenen verbrannt und verzehrt werden.

Die Kunde hat sich verbreitet. Ein Gesandter der {link:scourge}Geißel{/link}, {link:ambassador-malcin}Botschafter Malcin{/link}, wartet vor dem Tor und hat der Vettel geschrieben, die über den {link:razorfen-kraul}Kral{/link} herrscht. Die Nachtelfe {link:myriam-moonsinger}Myriam Moonsinger{/link} beobachtet das Labyrinth von einem Hügel im Süden aus. In {link:undercity}Undercity{/link} hat {link:varimathras}Varimathras{/link} von dem Gesandten erfahren, und in {link:stormwind-city}Stormwind{/link} hat {link:archbishop-benedictus}Erzbischof Benedictus{/link} von dem Lich gehört. Beide wollen ihn vernichtet sehen.]=],
		},
		{
			title = "In den Hügeln",
			text = [=[• {b}Das Tor.{/b} Der Bogen in Gestalt eines Eberrachens öffnet sich in den Dornen am Südrand des Brachlands. Kultisten der {link:death-s-head}Totenkopf{/link} und Stacheleberkrieger sammeln sich darum.
• {b}Die Pferche.{/b} Nahe dem Eingang halten die {link:quilboar}Stacheleber{/link} ihre Gefangenen. Unter ihnen sind ein Koch aus {link:stormwind-city}Stormwind{/link} namens {link:henry-stern}Henry Stern{/link} und ein Fremder, der sich {link:belnistrasz}Belnistrasz{/link} nennt.
• {b}Das Götzenbild.{/b} Ein großes Götzenbild nahe dem Tor dient den Stachelebern als Ofen für ihre Gefangenen.
• {b}Die Kammer des Gongs.{/b} Ein großer Gong hängt in einer von Netzen verhangenen Halle. Etwas Blindes und Hungriges wartet dahinter und lauscht.
• {b}Der Knochenhaufen.{/b} Ein toter Schamane, {link:mordresh-fire-eye}Mordresh Fire Eye{/link}, tanzt zwischen seinen skelettierten Brüdern auf einem Hügel aus Schädeln.
• {b}Die Dornenspirale.{/b} Ein Berg aus Ranken windet sich zum Gipfel hinauf, wo {link:amnennar-the-coldbringer}der Kältebringer{/link} Hof hält. {link:glutton}Glutton{/link} trottet über ihre unteren Pfade.]=],
		},
	},
})

Translate("deDE", "belnistrasz", {
	title = "Belnistrasz",
	subtitle = "Der Gefangene der Hügel",
	found = [=[Die Gefangenenpferche nahe dem Eingang der Hügel von Razorfen]=],
	hint = [=[Befreit den Fremden, der in den Pferchen der Hügel von Razorfen gefangen gehalten wird.]=],
	allegiance = "Keine erklärt",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Belnistrasz ist ein Gefangener der {link:quilboar}Stacheleber{/link}, zu finden in ihren Pferchen nahe dem Tor der Hügel von Razorfen. Er sieht aus wie ein Mensch, und er spricht mit dem gelassenen Mut eines Soldaten. Er hatte sich schon für tot gehalten, oder für eine Mahlzeit. Er sagt offen, dass die Stacheleber einen Handel mit der {link:scourge}Geißel{/link} geschlossen haben und dass {link:razorfen-downs}die Hügel{/link} der daraus geborene Albtraum sind. Einmal befreit, flieht er nicht. Er will dem Bösen hier einen Schlag versetzen, um aller Völker willen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Belnistrasz schert sich nicht um die Streitigkeiten von {link:horde}Horde{/link} und {link:alliance}Allianz{/link}. Er fragt nur, ob jene, die ihn befreien, sich einer Bedrohung für alle Völker entgegenstellen werden. Er ist auch in mehr als einem Sinne ein Fremder. Er gibt zu, dass er nicht aus diesen Landen stammt und dass bei seinesgleichen ein auf einen Stein geschworener Eid ein heiliges Band ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er überlebte die Gefangenschaft in den Pferchen der {link:death-s-head}Totenkopf{/link}.
• Er bot seinen Rettern einen Eidstein als Pfand der gemeinsamen Sache an.
• Er machte sich daran, das Götzenbild stillzulegen, an dem die {link:quilboar}Stacheleber{/link} ihre Gefangenen verbrannten.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Nichts ist darüber geschrieben, wie Belnistrasz in {link:razorfen-downs}die Hügel{/link} kam oder wohin er ging, als das Götzenbild erlosch.]=],
		},
	},
	chapters = {
		{
			title = "Der Eidstein",
			hint = "Schwört, dem befreiten Gefangenen beizustehen.",
			text = [=[Belnistrasz gab seinen Rettern einen Stein und bat sie, ihn ihm zurückzugeben, wenn sie sich ihm anschließen wollten. Sie taten es. Er verschwieg ihnen die Gefahr nicht. Die Arbeit, die vor ihnen liege, sei schwer, sagte er, doch wenn sie sich auf die Aufgabe besännen, könnten sie siegen.]=],
		},
		{
			title = "Das Götzenbild erlischt",
			hint = [=[Beschützt Belnistrasz, während er sein Ritual am Götzenbild wirkt.]=],
			text = [=[Das Götzenbild nahe dem Tor war ein grauenhafter Ofen, und Belnistrasz konnte es für immer binden, doch sein Ritual würde ihn wehrlos lassen. Seine Gefährten hielten die {link:death-s-head}Totenkopf{/link} fünf lange Minuten zurück, während er die Zeit ausrief. Endlich erloschen die Feuer. Belnistrasz war fort, und dort, wo er gestanden hatte, blieb nur ein brennendes Kohlenbecken zurück. In seinen Flammen erschien ein großer roter Drache mit gewaltigen Schwingen. Seine Stimme, nun tiefer, dankte den Sterblichen, die seinen Glauben an sie erneuert hatten.]=],
		},
	},
	bonds = {
		{ id = "plaguemaw-the-rotting", name = "Plaguemaw der Verrottende", note = "kam, um sein Ritual zu verhindern" },
		{ id = "henry-stern", name = "Henry Stern", note = "ein Mitgefangener" },
		{ id = "amnennar-the-coldbringer", name = "Amnennar der Kältebringer", note = "der Feind all dessen, was er verteidigt" },
	},
})

Translate("deDE", "amnennar-the-coldbringer", {
	title = "Amnennar der Kältebringer",
	subtitle = "Lich der Hügel von Razorfen",
	found = [=[Der Gipfel der Dornenspirale, tief in den Hügeln von Razorfen]=],
	hint = "Erklimmt die Dornenspirale zum Herrn der Hügel.",
	allegiance = "Geißel · Totenkopf",
	aliases = { "Amnennar", "der Kältebringer" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Amnennar der Kältebringer ist ein Lich, ein Diener des Lichkönigs und der Herr der Hügel von Razorfen. Er herrscht über die {link:death-s-head}Totenkopf{/link} von der Spitze einer großen Dornenspirale aus, zwischen kalten Feuern und ruhelosen Geistern. Es heißt, sein Geist sei so gewaltig, dass er die {link:quilboar}Stacheleber{/link} in allem lenkt, was sie tun. Wenn er bedroht wird, nennt er sich die Hand des Lichkönigs und ruft die gefrorenen Toten an seine Seite.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Amnennar hat der {link:scourge}Geißel{/link} eine Festung in {link:kalimdor}Kalimdor{/link} verschafft. Durch ihn erreicht die Seuche ein Volk, das sie nie gekannt hatte, und der Krieg, der {link:lordaeron}Lordaeron{/link} ein Ende bereitete, überquert das Meer. Es heißt, er habe mit der Geißel in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link} gekämpft, und der Lichkönig habe ihm danach befohlen zurückzubleiben und seine Macht zu verbreiten. Die {link:quilboar}Stacheleber{/link}, aus ihren Landen vertrieben, waren bereit, einem Herrn zuzuhören, der ihnen die Herrschaft über den Tod versprach.]=],
		},
		{
			title = "Taten",
			text = [=[• Er machte das heilige Labyrinth der {link:quilboar}Stacheleber{/link} zu einer Bastion der Untoten.
• Er erweckte die Toten der Hügel zu Skeletten und verdorrten Kriegern.
• Er band die {link:death-s-head}Totenkopf{/link} an seinen Willen.]=],
		},
	},
	chapters = {
		{
			title = "Bringt das Licht",
			hint = "Folgt dem Ruf des Erzbischofs, den Lich zu vernichten.",
			text = [=[In {link:stormwind-city}Stormwind{/link} erfuhr {link:archbishop-benedictus}Erzbischof Benedictus{/link}, dass die {link:quilboar}Stacheleber{/link} eines dornigen Labyrinths im {link:the-barrens}Brachland{/link} einen Pakt mit der {link:scourge}Geißel{/link} geschlossen hatten und dass ein Lich über sie herrschte. Er wartete nicht, bis das Böse wuchs. Er sandte Streiter des Lichts aus, um das Bündnis an seiner Wurzel zu beenden.]=],
		},
		{
			title = "Bringt das Ende",
			hint = "Bringt den Schädel des Kältebringers nach Undercity zurück.",
			text = [=[Die Verlassenen hielten {link:razorfen-downs}die Hügel{/link} zuerst für keine Bedrohung. Ihre späteren Berichte änderten ihre Meinung. {red:andrew-brownell}Andrew Brownell{/red} von den {link:royal-apothecary-society}Apothekern{/link} glaubte, dass Amnennar in Gedanken an {link:ner-zhul}Ner'zhul{/link} selbst gebunden war und dass dieses Band durchtrennt werden musste. Er verlangte den Schädel des Lichs.]=],
		},
	},
	mentions = {
		{ text = "Ein Heer des Bösen, die wachsenden Reihen der Hügel" },
	},
	bonds = {
		{ id = "belnistrasz", name = "Belnistrasz", note = "ein Feind all dessen, was er erbaut" },
		{ id = "mordresh-fire-eye", name = "Mordresh Fire Eye", note = "sein Diener" },
		{ id = "glutton", name = "Glutton", note = "sein Diener" },
		{ id = "ambassador-malcin", name = "Botschafter Malcin", note = "ein Mitdiener des Lichkönigs" },
	},
})

Translate("deDE", "tuten-kash", {
	title = "Tuten'kash",
	subtitle = "Die wartende Gruftbestie",
	found = "Die Kammer des Gongs, Hügel von Razorfen",
	hint = "Schlagt den großen Gong der Hügel und seht, was antwortet.",
	allegiance = "Geißel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tuten'kash ist eine Gruftbestie der {link:scourge}Geißel{/link}, eine der großen Spinnenwesen, die der Lichkönig von den Toten erweckte. Er verbirgt sich in einem Hort aus Netzen in den Tiefen der Hügel von Razorfen. Es heißt, er sei blind und seine feinen Fäden verrieten ihm jeden Schritt in seiner Nähe. Ein großer Gong hängt in der Halle vor seinem Hort. Wenn er ertönt, kommen zuerst geringere Bestien, dann größere, und zuletzt Tuten'kash selbst.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Tuten'kash ist ein Zeichen dafür, dass die {link:scourge}Geißel{/link} mehr als Knochen und Seuche über das Meer geschickt hat. Die Spinnenwesen des hohen Nordens warten nun unter den Dornen des Brachlands.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bewacht die Tiefen der Hügel mit seinen Grabbestien und Häschern.]=],
		},
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar der Kältebringer", note = "sein Herr in den Hügeln" },
	},
})

Translate("deDE", "mordresh-fire-eye", {
	title = "Mordresh Fire Eye",
	subtitle = "Der tote Schamane",
	found = "Der Knochenhaufen, Hügel von Razorfen",
	hint = "Sucht das Skelett, das auf dem Knochenhügel tanzt.",
	allegiance = "Geißel",
	aliases = { "Mordresh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mordresh Fire Eye ist ein skelettierter Zauberwirker der {link:scourge}Geißel{/link}, der in den Hügeln von Razorfen auf einem Hügel aus Schädeln steht und zwischen seinen knöchernen Brüdern tanzt. Es heißt, er sei einst ein orcischer Schamane gewesen, aus {link:orgrimmar}Orgrimmar{/link} entsandt, um herauszufinden, was sich in den Hügeln regte. Er wurde erschlagen, und der Herr der Hügel erweckte ihn erneut. Nun verbrennt er die Lebenden mit Feuer und stachelt die geringeren Toten zur Raserei an. Er prahlt vor seinesgleichen, dass sie die {link:quilboar}Stacheleber{/link} versklaven und sich über das {link:the-barrens}Brachland{/link} ausbreiten werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wenn die Geschichte seiner Vergangenheit wahr ist, ist Mordresh der erste Verlust der {link:horde}Horde{/link} an die {link:scourge}Geißel{/link} in {link:kalimdor}Kalimdor{/link}.]=],
		},
		{ title = "Taten", text = "• Er führt die Skelette des Knochenhaufens an." },
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar der Kältebringer", note = "der Herr, der ihn erweckte" },
	},
})

Translate("deDE", "glutton", {
	title = "Glutton",
	subtitle = "Die Monstrosität der Hügel",
	found = "Die unteren Pfade der Dornenspirale, Hügel von Razorfen",
	hint = [=[Hütet Euch vor dem zusammengenähten Riesen, der durch die untere Dornenspirale streift.]=],
	allegiance = "Geißel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Glutton ist eine Monstrosität, ein Koloss aus zusammengenähtem Fleisch, geschaffen von den Nekromanten der {link:scourge}Geißel{/link}. Er wandert über die unteren Pfade der Dornenspirale und hungert ohne Ende. Es heißt, er nähre sich von den verwesenden Toten der Hügel, Ebern wie Stachelebern, und eine Wolke der Krankheit steige aus dem Aas in seinem Bauch auf. Je länger er kämpft, desto hungriger und wilder wird er.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Glutton ist die Art Schrecken, den die {link:scourge}Geißel{/link} nach {link:lordaeron}Lordaeron{/link} brachte, nun unter den Stachelebern losgelassen.]=],
		},
		{ title = "Taten", text = "• Er streift im Auftrag seines Herrn über die Dornenspirale." },
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar der Kältebringer", note = "sein Herr" },
	},
})

Translate("deDE", "plaguemaw-the-rotting", {
	title = "Plaguemaw der Verrottende",
	subtitle = "Verteidiger des Götzenbilds",
	found = [=[Das Götzenbild nahe dem Eingang der Hügel von Razorfen, während Belnistrasz' Ritual]=],
	hint = "Steht Belnistrasz am Götzenbild bis zum Ende bei.",
	allegiance = "Totenkopf · Geißel",
	aliases = { "Plaguemaw" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Plaguemaw der Verrottende ist ein untoter {link:quilboar}Stacheleber{/link} der {link:death-s-head}Totenkopf{/link}, ein Koloss aus verwesendem Fleisch und Seuche. Er wartete in keiner Kammer der Hügel. Er kam erst aus der Dunkelheit hervor, als {link:belnistrasz}Belnistrasz{/link} sein Ritual begann, um das Götzenbild der Stacheleber zu binden, und er kam, um es zu verhindern. Sein Gestank schwächt den stärksten Arm, und seine Berührung macht den Körper krank und zehrt am Geist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Plaguemaw zeigt, was aus den Stachelebern unter dem Lich geworden ist: Ihre Toten werden nicht mehr geehrt, sondern erweckt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kämpfte darum, das Götzenbild der {link:quilboar}Stacheleber{/link} vor {link:belnistrasz}Belnistrasz{/link}' Ritual zu bewahren.]=],
		},
	},
	bonds = {
		{ id = "belnistrasz", name = "Belnistrasz", note = "der Feind, den er aufhalten wollte" },
	},
})

Translate("deDE", "ragglesnout", {
	title = "Ragglesnout",
	subtitle = "Priester der Totenkopf",
	found = "Die Dornenspirale, Hügel von Razorfen, nur zuweilen zu sehen",
	hint = [=[Haltet auf der Dornenspirale Ausschau nach einem Stacheleberpriester, der selten zu sehen ist.]=],
	allegiance = "Totenkopf",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ragglesnout ist ein {link:quilboar}Stacheleber{/link} der {link:death-s-head}Totenkopf{/link}, der selten zu sehen ist, und nur auf den Pfaden der Dornenspirale. Er lebt noch, und doch dient er dem Lich. Er wirkt Schattenmagie, heilt seine Verbündeten und kann einen schwächeren Geist seinem Willen beugen. Wenn er erscheint, dann auf den Pfaden unterhalb des Gipfels des Lichs, nicht weit von dort, wo {link:glutton}Glutton{/link} umherstreift.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ragglesnout zeigt, dass nicht jeder Priester der {link:death-s-head}Totenkopf{/link} sterben musste, um der {link:scourge}Geißel{/link} zu dienen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wandelt zwischen den Dienern Amnennars auf der Dornenspirale.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Nichts ist über Ragglesnouts Vergangenheit geschrieben oder darüber, warum er so selten zu sehen ist.]=],
		},
	},
	bonds = {
		{ id = "amnennar-the-coldbringer", name = "Amnennar der Kältebringer", note = "der Herr, dem er dient" },
	},
})

Translate("deDE", "henry-stern", {
	title = "Henry Stern",
	subtitle = "Koch und Alchemist aus Stormwind",
	found = [=[Die Gefangenenpferche nahe dem Eingang der Hügel von Razorfen]=],
	hint = [=[Befreit den Koch, der in den Pferchen der Hügel von Razorfen gefangen gehalten wird.]=],
	allegiance = "Königreich Stormwind",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Henry Stern ist ein Koch und Alchemist aus {link:stormwind-city}Stormwind{/link}. Er kam ins {link:the-barrens}Brachland{/link}, um für seinen Onkel Angus heimische Kräuter und Rezepte zu sammeln. Die {link:quilboar}Stacheleber{/link} fingen ihn und warfen ihn in ihre Pferche. Er ist sicher, dass er in ihrem Kochtopf geendet wäre. Einmal befreit, bleibt er, wo er ist, und wartet, bis der Weg hinaus sicher ist. Gern teilt er, was er über die Kräuter des Brachlands gelernt hat, darunter den Golddorn.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Henry Stern ist der Beweis dafür, wozu das Götzenbild nahe dem Tor diente. Die {link:quilboar}Stacheleber{/link} nahmen keine Gefangenen, um Lösegeld zu fordern.]=],
		},
		{
			title = "Taten",
			text = [=[• Er überlebte die Gefangenschaft in den Hügeln.
• Er lehrt jene, die sein Handwerk teilen, die Rezepte für Golddorntee und Trollblut.]=],
		},
	},
	bonds = {
		{ id = "belnistrasz", name = "Belnistrasz", note = "ein Mitgefangener" },
	},
})

Translate("deDE", "myriam-moonsinger", {
	title = "Myriam Moonsinger",
	subtitle = "Wächterin der Hügel",
	found = "Ein Hügel gleich südlich des Tors der Hügel von Razorfen",
	hint = [=[Sucht die Nachtelfe, die von einem südlichen Hügel aus die Dornen der Hügel bewacht.]=],
	allegiance = "Nachtelfen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Myriam Moonsinger ist eine Späherin der {link:night-elves}Nachtelfen{/link}, die von einem Hügel neben dem Tor aus über {link:razorfen-downs}die Hügel{/link} von Razorfen wacht. Ihr Volk spürte eine Dunkelheit, die von diesem Ort ausging, und sandte sie aus, um zu erfahren, was es war. Was sie gefunden hat, beunruhigt sie. Ein untoter Diplomat ist zu den Stachelebern gekommen, einer, der in arkaner Magie bewandert ist, und sie glaubt nicht, dass er einer der {link:forsaken}Verlassenen{/link} ist. Sie fürchtet, dass er etwas Schlimmeres ist.]=],
		},
		{
			title = "Bedeutung",
