Translate("deDE", "death-s-head", {
	title = "Totenkopf",
	aliases = { "Totenkopfstamm", "Totenkopfkult" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Totenkopf sind die Hohepriester der {link:quilboar}Stacheleber{/link}, die Hüter der Begräbnisstätten der Hügel von Razorfen. Sie haben sich der {link:scourge}Geißel{/link} zugewandt. Unter dem Lich {link:amnennar-the-coldbringer}Amnennar{/link} dem Kältebringer dienen sie dem Untod am heiligsten Ort ihres Volkes, und viele ihrer Krieger wandeln nun als verdorrte Leichname.]=],
		},
		{
			title = "Der Handel",
			text = [=[Niemand außerhalb der Hügel kennt die ganze Wahrheit darüber, wie es begann. Die {link:scourge}Geißel{/link} sandte einen Gesandten, {link:ambassador-malcin}Botschafter Malcin{/link}, der den Stachelebern das {link:the-barrens}Brachland{/link} und mehr als Gegenleistung für ihre Hilfe anbot. {link:varimathras}Varimathras{/link} glaubt, dass {link:charlga-razorflank}die Vettel{/link} des {link:razorfen-kraul}Krals von Razorfen{/link} sich aus dem Handel heraushielt. Die Priester der Hügel taten es nicht. Manche aus ihrem Stamm sind erschreckend stark geworden und tragen die Male der Seuche. Die Nachtelfe {link:myriam-moonsinger}Myriam Moonsinger{/link} sah {link:quilboar}Stacheleber{/link} jeden Tag aus den Schatten kriechen, um den Gesandten um mehr Macht anzuflehen.]=],
		},
		{
			title = "Die Ordnung",
			text = [=[Priester, Nekromanten, Geomanten und Kultisten der Totenkopf dienen dem Lich an der Seite lebender Stacheleberkrieger und Dornenwirker. Verdorrte {link:quilboar}Stacheleber{/link}, Kampfeber und Skelette füllen ihre Reihen. Unter ihnen sind {link:ragglesnout}Ragglesnout{/link}, der noch lebt, und {link:plaguemaw-the-rotting}Plaguemaw der Verrottende{/link}, der es nicht tut. Ihre Gefangenen werden in Pferchen nahe dem Tor gehalten, und wer nicht gerettet wird, wird vor dem Götzenbild verbrannt und verzehrt.]=],
		},
	},
})
